-- Stock schema-32 storage contract, including empty deferred tables.
CREATE TABLE btech_autopilot_command_args ( autopilot_dbref INTEGER NOT NULL, command_position INTEGER NOT NULL, argument_index INTEGER NOT NULL, value TEXT NOT NULL, PRIMARY KEY (autopilot_dbref, command_position, argument_index)) WITHOUT ROWID;
