CREATE TABLE btech_autopilots ( dbref INTEGER PRIMARY KEY, unit_dbref INTEGER NOT NULL, map_dbref INTEGER NOT NULL, speed_percent INTEGER NOT NULL, offset_x INTEGER NOT NULL, offset_y INTEGER NOT NULL, verbose_level INTEGER NOT NULL, target INTEGER NOT NULL, target_score INTEGER NOT NULL, target_threshold INTEGER NOT NULL, target_update_tick INTEGER NOT NULL, chase_target INTEGER NOT NULL, chase_update_tick INTEGER NOT NULL, follow_update_tick INTEGER NOT NULL, flags INTEGER NOT NULL, unit_max_range INTEGER NOT NULL, roam_type INTEGER NOT NULL, roam_update_tick INTEGER NOT NULL, roam_target_x INTEGER NOT NULL, roam_target_y INTEGER NOT NULL, roam_anchor_x INTEGER NOT NULL, roam_anchor_y INTEGER NOT NULL, roam_anchor_distance INTEGER NOT NULL, ahead_ok INTEGER NOT NULL, auto_cmode INTEGER NOT NULL, auto_cdist INTEGER NOT NULL, auto_goweight INTEGER NOT NULL, auto_fweight INTEGER NOT NULL, auto_nervous INTEGER NOT NULL, b_msc INTEGER NOT NULL, w_msc INTEGER NOT NULL, b_bsc INTEGER NOT NULL, w_bsc INTEGER NOT NULL, b_dan INTEGER NOT NULL, w_dan INTEGER NOT NULL, last_upd INTEGER NOT NULL, engaged INTEGER NOT NULL CHECK (engaged IN (0, 1)));
