CREATE TABLE btech_economy_parts ( object_dbref INTEGER NOT NULL REFERENCES objects(dbref) ON DELETE CASCADE, part_id INTEGER NOT NULL, quantity INTEGER NOT NULL CHECK (quantity > 0), PRIMARY KEY (object_dbref, part_id)) WITHOUT ROWID;
