CREATE TABLE btech_unit_runtime ( unit_dbref INTEGER PRIMARY KEY, jumptop INTEGER NOT NULL, aim INTEGER NOT NULL, basetohit INTEGER NOT NULL, pilotskillbase INTEGER NOT NULL, engineheat INTEGER NOT NULL, masc_value INTEGER NOT NULL, aim_type INTEGER NOT NULL, sensor_primary INTEGER NOT NULL, sensor_secondary INTEGER NOT NULL, fire_adjustment INTEGER NOT NULL, vis_mod INTEGER NOT NULL, charge_timer INTEGER NOT NULL, charge_distance REAL NOT NULL, stagger_stamp INTEGER NOT NULL, unit_prefs INTEGER NOT NULL, jump_length INTEGER NOT NULL, going_x INTEGER NOT NULL, going_y INTEGER NOT NULL, desired_facing INTEGER NOT NULL, angle INTEGER NOT NULL, jump_heading INTEGER NOT NULL, target_x INTEGER NOT NULL, target_y INTEGER NOT NULL, target_z INTEGER NOT NULL, turret_facing INTEGER NOT NULL, turn_damage INTEGER NOT NULL, lateral INTEGER NOT NULL, num_seen INTEGER NOT NULL, lx INTEGER NOT NULL, ly INTEGER NOT NULL, charge_target INTEGER NOT NULL, dfa_target INTEGER NOT NULL, target INTEGER NOT NULL, swarming INTEGER NOT NULL, swarmed_by INTEGER NOT NULL, carrying INTEGER NOT NULL, spotter INTEGER NOT NULL, heat REAL NOT NULL, weapon_heat REAL NOT NULL, plus_heat REAL NOT NULL, minus_heat REAL NOT NULL, start_fx REAL NOT NULL, start_fy REAL NOT NULL, start_fz REAL NOT NULL, end_fz REAL NOT NULL, vertical_speed REAL NOT NULL, speed REAL NOT NULL, desired_speed REAL NOT NULL, jump_speed REAL NOT NULL, crit_status INTEGER NOT NULL, status INTEGER NOT NULL, status2 INTEGER NOT NULL, specials INTEGER NOT NULL, specials2 INTEGER NOT NULL, specials_status INTEGER NOT NULL, tank_crit_status INTEGER NOT NULL, last_weapon_recycle INTEGER NOT NULL, cargo_weight INTEGER NOT NULL, last_random_update INTEGER NOT NULL, random_seed INTEGER NOT NULL, last_ds_message INTEGER NOT NULL, boom_start INTEGER NOT NULL, max_fuel INTEGER NOT NULL, last_used INTEGER NOT NULL, cocoon INTEGER NOT NULL, commconv INTEGER NOT NULL, commconv_last INTEGER NOT NULL, original_heat_sinks INTEGER NOT NULL, disable