CREATE TABLE btech_unit_sections ( unit_dbref INTEGER NOT NULL, section INTEGER NOT NULL, armor INTEGER NOT NULL, internal INTEGER NOT NULL, rear INTEGER NOT NULL, armor_original INTEGER NOT NULL, internal_original INTEGER NOT NULL, rear_original INTEGER NOT NULL, base_to_hit INTEGER NOT NULL, config INTEGER NOT NULL, recycle INTEGER NOT NULL, specials INTEGER NOT NULL, PRIMARY KEY (unit_dbref, section)) WITHOUT ROWID;
CREATE TABLE btech_unit_stagger_damage ( unit_dbref INTEGER NOT NULL, position INTEGER NOT NULL, amount INTEGER NOT NULL, occurred_at INTEGER NOT NULL, attacker_dbref INTEGER NOT NULL, counted INTEGER NOT NULL, PRIMARY KEY (unit_dbref, position)) WITHOUT ROWID;
