CREATE TABLE objects ( dbref INTEGER PRIMARY KEY, name TEXT NOT NULL, location INTEGER NOT NULL, zone INTEGER NOT NULL, affiliation INTEGER NOT NULL DEFAULT -1, contents INTEGER NOT NULL, exits INTEGER NOT NULL, link INTEGER NOT NULL, next INTEGER NOT NULL, type INTEGER NOT NULL CHECK (type IN (0, 1, 2, 3, 5)), lua_parent TEXT NOT NULL DEFAULT '', description TEXT, internal_description TEXT, has_ansi_flag INTEGER NOT NULL DEFAULT 0 CHECK (has_ansi_flag IN (0, 1)), has_audible_flag INTEGER NOT NULL DEFAULT 0 CHECK (has_audible_flag IN (0, 1)), has_auditorium_flag INTEGER NOT NULL DEFAULT 0 CHECK (has_auditorium_flag IN (0, 1)), has_blind_flag INTEGER NOT NULL DEFAULT 0 CHECK (has_blind_flag IN (0, 1)), has_connected_flag INTEGER NOT NULL DEFAULT 0 CHECK (has_connected_flag IN (0, 1)), has_dark_flag INTEGER NOT NULL DEFAULT 0 CHECK (has_dark_flag IN (0, 1)), has_floating_flag INTEGER NOT NULL DEFAULT 0 CHECK (has_floating_flag IN (0, 1)), has_gagged_flag INTEGER NOT NULL DEFAULT 0 CHECK (has_gagged_flag IN (0, 1)), has_going_flag INTEGER NOT NULL DEFAULT 0 CHECK (has_going_flag IN (0, 1)), has_halted_flag INTEGER NOT NULL DEFAULT 0 CHECK (has_halted_flag IN (0, 1)), has_in_character_flag INTEGER NOT NULL DEFAULT 0 CHECK (has_in_character_flag IN (0, 1)), has_light_flag INTEGER NOT NULL DEFAULT 0 CHECK (has_light_flag IN (0, 1)), has_monitor_flag INTEGER NOT NULL DEFAULT 0 CHECK (has_monitor_flag IN (0, 1)), has_no_command_flag INTEGER NOT NULL DEFAULT 0 CHECK (has_no_command_flag IN (0, 1)), has_safe_flag INTEGER NOT NULL DEFAULT 0 CHECK (has_safe_flag IN (0, 1)), has_suspect_flag INTEGER NOT NULL DEFAULT 0 CHECK (has_suspect_flag IN (0, 1)), has_transparent_flag INTEGER NOT NULL DEFAULT 0 CHECK (has_transparent_flag IN (0, 1)), has_wizard_flag INTEGER NOT NULL DEFAULT 0 CHECK (has_wizard_flag IN (0, 1)), has_zombie_flag INTEGER NOT NULL DEFAULT 0 CHECK (has_zombie_flag IN (0, 1)), has_idle_power INTEGER NOT NULL DEFAULT 0 CHECK (has_idle_power IN (0, 1)));
CREATE TABLE player_last_page_recipients ( player_dbref INTEGER NOT NULL REFERENCES player_state(object_dbref) ON DELETE CASCADE, position INTEGER NOT NULL CHECK (position >= 0), recipient_dbref INTEGER NOT NULL, PRIMARY KEY (player_dbref, position)) WITHOUT ROWID;
CREATE TABLE player_login_history ( player_dbref INTEGER NOT NULL REFERENCES player_state(object_dbref) ON DELETE CASCADE, outcome INTEGER NOT NULL CHECK (outcome IN (0, 1)), position INTEGER NOT NULL CHECK (position >= 0 AND ((outcome = 0 AND position < 4) OR (outcome = 1 AND position < 3))), occurred_at INTEGER NOT NULL, host TEXT NOT NULL, PRIMARY KEY (player_dbref, outcome, position)) WITHOUT ROWID;
CREATE TABLE player_state ( object_dbref INTEGER PRIMARY KEY REFERENCES objects(dbref), password_hash TEXT, alias TEXT, last_login INTEGER, last_site TEXT, successful_login_count INTEGER NOT NULL DEFAULT 0 CHECK (successful_login_count >= 0), failed_login_count INTEGER NOT NULL DEFAULT 0 CHECK (failed_login_count >= 0), unreported_failed_login_count INTEGER NOT NULL DEFAULT 0 CHECK (unreported_failed_login_count >= 0 AND unreported_failed_login_count <= failed_login_count));
CREATE TABLE snapshot ( id INTEGER PRIMARY KEY CHECK (id = 1), schema_version INTEGER NOT NULL, storage_format INTEGER NOT NULL, storage_version INTEGER NOT NULL, dump_type INTEGER NOT NULL, dump_time INTEGER NOT NULL, db_top INTEGER NOT NULL, min_size INTEGER NOT NULL, record_players INTEGER NOT NULL);
